311		onlyA := filepath.Join(dir, "a.json")
312		aB := filepath.Join(dir, "ab.json")
313		pA := writeFile(t, "a.json", `{"datasets":[{"name":"A","upstreams":[]}]}`)
314		pAB := writeFile(t, "ab.json", `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`)
315		if _, _, exit := captureStdout(t, func() int { return run([]string{"snapshot", pA, onlyA}) }); exit != 0 {
316			t.Fatalf("snapshot a")
317		}
318		if _, _, exit := captureStdout(t, func() int { return run([]string{"snapshot", pAB, aB}) }); exit != 0 {
319			t.Fatalf("snapshot ab")
320		}
321	
322		stdout, _, exit := captureStdout(t, func() int { return run([]string{"compare", onlyA, aB}) })
323		if exit != 0 {
324			t.Fatalf("compare")
325		}
326		var forward chainledger.CompareReport
327		if err := json.Unmarshal([]byte(stdout), &forward); err != nil {
328			t.Fatalf("json: %v", err)
