330		if !reflect.DeepEqual(forward.NewDatasets, []string{"B"}) || len(forward.RemovedDatasets) != 0 {
331			t.Errorf("old->new direction wrong: new=%v removed=%v", forward.NewDatasets, forward.RemovedDatasets)
