347	// TestCLISnapshotConcurrentSamesContent exercises the flock-guarded
348	// check-then-write from within one process: every concurrent save of identical
349	// content succeeds, and the resulting file is a single valid snapshot.
350	func TestCLISnapshotConcurrentSameContent(t *testing.T) {
351		dir := t.TempDir()
352		target := filepath.Join(dir, "snap.json")
353	
354		// Discard the per-call success lines so concurrent writes do not interleave
355		// into the test's own stdout pipe.
356		devNull, err := os.OpenFile(os.DevNull, os.O_WRONLY, 0)
357		if err != nil {
358			t.Fatalf("open devnull: %v", err)
359		}
360		defer devNull.Close()
361		oldOut, oldErr := os.Stdout, os.Stderr
362		os.Stdout, os.Stderr = devNull, devNull
363		defer func() { os.Stdout, os.Stderr = oldOut, oldErr }()
364	
365		const n = 16
366		graphPath := writeFile(t, "g.json", abcGraph)
367		var wg sync.WaitGroup
368		codes := make(chan int, n)
369		for i := 0; i < n; i++ {
370			wg.Add(1)
371			go func() {
372				defer wg.Done()
373				codes <- run([]string{"snapshot", graphPath, target})
374			}()
375		}
376		wg.Wait()
377		close(codes)
378		for code := range codes {
379			if code != 0 {
380				t.Errorf("concurrent same-content save exit = %d, want 0", code)
381			}
382		}
383		if _, err := chainledger.ParseSnapshot([]byte(readFile(t, target))); err != nil {
384			t.Errorf("target invalid after concurrent saves: %v", err)
385		}
386	}
