388	func TestCLIHelpMentionsSnapshotCommands(t *testing.T) {
389		stdout, _, exit := captureStdout(t, func() int { return run([]string{"help"}) })
390		if exit != 0 {
391			t.Fatalf("help exit = %d", exit)
392		}
393		for _, want := range []string{"snapshot", "compare", "preview", "apply"} {
394			if !strings.Contains(stdout, want) {
395				t.Errorf("help missing %q:\n%s", want, stdout)
396			}
397		}
398	}
