400	// dupFieldSnapshot produces a snapshot of graphJSON whose bytes then have one
401	// known field declared a second time, so the document is ambiguous even
402	// though the surviving values still describe the same graph.
403	func dupFieldSnapshot(t *testing.T, graphJSON string) (path string, content string) {
404		t.Helper()
405		target := filepath.Join(t.TempDir(), "snap.json")
406		if _, stderr, exit := snapshotViaCLI(t, graphJSON, target); exit != 0 {
407			t.Fatalf("seed snapshot: %s", stderr)
408		}
409		valid := readFile(t, target)
410		// Drop the lock file left by the seeding save so callers can assert that
411		// compare/trace create no lock of their own.
412		if err := os.Remove(target + ".lock"); err != nil {
413			t.Fatalf("remove seed lock: %v", err)
414		}
415		// Declare formatVersion twice: first 2, then the valid 1. The reader would
416		// silently keep the 1 and every other check would pass.
417		dup := strings.Replace(valid, `"formatVersion": 1`, `"formatVersion": 2, "formatVersion": 1`, 1)
418		if dup == valid {
419			t.Fatalf("could not inject duplicate field into %s", valid)
420		}
421		return target, dup
422	}
423	
424	func TestCLICompareRejectsDuplicateFields(t *testing.T) {
425		dir := t.TempDir()
426		good := filepath.Join(dir, "good.json")
427		if _, stderr, exit := snapshotViaCLI(t, abcGraph, good); exit != 0 {
428			t.Fatalf("snapshot good: %s", stderr)
429		}
430		dupPath, dupContent := dupFieldSnapshot(t, abcGraph)
431		if err := os.WriteFile(dupPath, []byte(dupContent), 0o644); err != nil {
432			t.Fatalf("write dup: %v", err)
433		}
434	
435		for _, tc := range []struct {
436			name string
437			args []string
438			side string
439		}{
440			{"duplicate in old snapshot", []string{"compare", dupPath, good}, "old snapshot"},
441			{"duplicate in new snapshot", []string{"compare", good, dupPath}, "new snapshot"},
442		} {
443			t.Run(tc.name, func(t *testing.T) {
444				stdout, stderr, exit := captureStdout(t, func() int { return run(tc.args) })
445				if exit == 0 {
446					t.Fatalf("%v succeeded, want failure", tc.args)
447				}
448				if stdout != "" {
449					t.Errorf("stdout = %q, want empty on rejection", stdout)
450				}
451				if !strings.Contains(stderr, tc.side) || !strings.Contains(stderr, dupPath) {
452					t.Errorf("stderr = %q, must name the %s file", stderr, tc.side)
453				}
454				if !strings.Contains(stderr, "formatVersion") {
455					t.Errorf("stderr = %q, must name the duplicated field", stderr)
456				}
457				// compare stays read-only and never creates a lock file.
458				if got := readFile(t, dupPath); got != dupContent {
459					t.Errorf("compare modified the snapshot:\n%s", got)
460				}
461				if _, err := os.Stat(dupPath + ".lock"); !os.IsNotExist(err) {
462					t.Errorf("compare created a lock file: %v", err)
463				}
464			})
465		}
466	}
467	
468	func TestCLITraceRejectsDuplicateFields(t *testing.T) {
469		dupPath, dupContent := dupFieldSnapshot(t, abcGraph)
470		if err := os.WriteFile(dupPath, []byte(dupContent), 0o644); err != nil {
471			t.Fatalf("write dup: %v", err)
472		}
473	
474		stdout, stderr, exit := captureStdout(t, func() int {
475			return run([]string{"trace", dupPath, "C"})
476		})
477		if exit == 0 {
478			t.Fatalf("trace succeeded on an ambiguous snapshot")
479		}
480		if stdout != "" {
481			t.Errorf("stdout = %q, want empty on rejection", stdout)
482		}
483		if !strings.Contains(stderr, dupPath) || !strings.Contains(stderr, "formatVersion") {
484			t.Errorf("stderr = %q, must name the file and the duplicated field", stderr)
485		}
486		if got := readFile(t, dupPath); got != dupContent {
487			t.Errorf("trace modified the snapshot:\n%s", got)
488		}
489		if _, err := os.Stat(dupPath + ".lock"); !os.IsNotExist(err) {
490			t.Errorf("trace created a lock file: %v", err)
491		}
